from collections import OrderedDict

def cache_trace(capacity, ops):
    store = OrderedDict()
    out = []
    for op in ops:
        kind = op[0]
        if kind == "put":
            k, v = op[1], op[2]
            if capacity <= 0:
                continue
            if k in store:
                store.pop(k)
            store[k] = v
            if len(store) > capacity:
                store.popitem(last=False)
        elif kind == "get":
            k = op[1]
            if k in store:
                v = store.pop(k)
                store[k] = v
                out.append(v)
            else:
                out.append(None)
        else:
            k = op[1]
            out.append(store.get(k, None))
    return out

from fractions import Fraction

def evaluate(expr):
    if not isinstance(expr, str):
        return None
    s = expr
    n = len(s)
    pos = 0

    class Bad(Exception):
        pass

    def skip():
        nonlocal pos
        while pos < n and s[pos] == " ":
            pos += 1

    def parse_expr():
        nonlocal pos
        val = parse_term()
        while True:
            skip()
            if pos < n and s[pos] in "+-":
                op = s[pos]
                pos += 1
                rhs = parse_term()
                val = val + rhs if op == "+" else val - rhs
            else:
                return val

    def parse_term():
        nonlocal pos
        val = parse_factor()
        while True:
            skip()
            if pos < n and s[pos] in "*/":
                op = s[pos]
                pos += 1
                rhs = parse_factor()
                if op == "*":
                    val = val * rhs
                else:
                    if rhs == 0:
                        raise Bad()
                    val = val / rhs
            else:
                return val

    def parse_factor():
        nonlocal pos
        skip()
        if pos < n and s[pos] in "+-":
            op = s[pos]
            pos += 1
            v = parse_factor()
            return v if op == "+" else -v
        return parse_power()

    def parse_power():
        nonlocal pos
        base = parse_atom()
        skip()
        if pos < n and s[pos] == "^":
            pos += 1
            e = parse_factor()
            if e.denominator != 1:
                raise Bad()
            e = int(e)
            if base == 0 and e < 0:
                raise Bad()
            return base ** e
        return base

    def parse_atom():
        nonlocal pos
        skip()
        if pos >= n:
            raise Bad()
        if s[pos] == "(":
            pos += 1
            v = parse_expr()
            skip()
            if pos >= n or s[pos] != ")":
                raise Bad()
            pos += 1
            return v
        start = pos
        seen_dot = False
        while pos < n and (s[pos].isdigit() or (s[pos] == "." and not seen_dot)):
            if s[pos] == ".":
                seen_dot = True
            pos += 1
        tok = s[start:pos]
        if tok in ("", "."):
            raise Bad()
        return Fraction(tok)

    try:
        v = parse_expr()
        skip()
        if pos != n:
            return None
        return float(v)
    except Bad:
        return None
    except Exception:
        return None

def glob_match(pattern, text):
    p = pattern
    t = text
    np_ = len(p)
    nt = len(t)

    def parse_class(i):
        # p[i] == '['; returns (matcher_set_fn, next_index) or None if not a valid class
        j = i + 1
        neg = False
        if j < np_ and p[j] == "!":
            neg = True
            j += 1
        items = []
        first = True
        while j < np_ and (p[j] != "]" or first):
            if j + 2 < np_ and p[j + 1] == "-" and p[j + 2] != "]":
                items.append((p[j], p[j + 2]))
                j += 3
            else:
                items.append((p[j], p[j]))
                j += 1
            first = False
        if j >= np_:
            return None
        return (neg, items, j + 1)

    # dp[i][j] : pattern[i:] matches text[j:]
    prev = [False] * (nt + 1)
    rows = []
    # precompute segments of the pattern
    segs = []
    i = 0
    while i < np_:
        if p[i] == "[":
            parsed = parse_class(i)
            if parsed is None:
                segs.append(("lit", "["))
                i += 1
            else:
                neg, items, nxt = parsed
                segs.append(("cls", (neg, items)))
                i = nxt
        elif p[i] == "*":
            segs.append(("star", None))
            i += 1
        elif p[i] == "?":
            segs.append(("any", None))
            i += 1
        else:
            segs.append(("lit", p[i]))
            i += 1

    ns = len(segs)
    dp = [[False] * (nt + 1) for _ in range(ns + 1)]
    dp[ns][nt] = True
    for si in range(ns, -1, -1):
        for tj in range(nt, -1, -1):
            if si == ns:
                continue
            kind, data = segs[si]
            if kind == "star":
                ok = dp[si + 1][tj] or (tj < nt and dp[si][tj + 1])
            elif tj >= nt:
                ok = False
            elif kind == "any":
                ok = dp[si + 1][tj + 1]
            elif kind == "lit":
                ok = (t[tj] == data) and dp[si + 1][tj + 1]
            else:
                neg, items = data
                c = t[tj]
                inside = any(lo <= c <= hi for lo, hi in items)
                ok = (inside != neg) and dp[si + 1][tj + 1]
            dp[si][tj] = ok
    return dp[0][0]

def recurrence_term(coeffs, init, n):
    MOD = 1000000007
    k = len(coeffs)
    if n < k:
        return init[n] % MOD
    def mul(A, B):
        size = k
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            Ai = A[i]
            Ci = C[i]
            for x in range(size):
                a = Ai[x]
                if a:
                    Bx = B[x]
                    for j in range(size):
                        Ci[j] = (Ci[j] + a * Bx[j]) % MOD
        return C
    M = [[0] * k for _ in range(k)]
    for j in range(k):
        M[0][j] = coeffs[j] % MOD
    for i in range(1, k):
        M[i][i - 1] = 1
    R = [[1 if i == j else 0 for j in range(k)] for i in range(k)]
    e = n - (k - 1)
    base = M
    while e:
        if e & 1:
            R = mul(R, base)
        base = mul(base, base)
        e >>= 1
    vec = [init[k - 1 - i] % MOD for i in range(k)]
    return sum(R[0][i] * vec[i] for i in range(k)) % MOD

