def hull_double_area(points):
    pts = sorted(set(points))
    if len(pts) < 3:
        return 0

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    hull = lower[:-1] + upper[:-1]
    if len(hull) < 3:
        return 0
    area2 = 0
    for i in range(len(hull)):
        x1, y1 = hull[i]
        x2, y2 = hull[(i + 1) % len(hull)]
        area2 += x1 * y2 - x2 * y1
    return abs(area2)

from collections import deque

def ladder_length(start, goal, words):
    wordset = set(words)
    if goal not in wordset:
        return 0
    if start == goal:
        return 1
    L = len(start)
    buckets = {}
    for w in wordset:
        if len(w) != L:
            continue
        for i in range(L):
            buckets.setdefault(w[:i] + "*" + w[i + 1:], []).append(w)
    seen = {start}
    q = deque([(start, 1)])
    while q:
        w, d = q.popleft()
        for i in range(L):
            key = w[:i] + "*" + w[i + 1:]
            for nxt in buckets.get(key, ()):
                if nxt in seen:
                    continue
                if nxt == goal:
                    return d + 1
                seen.add(nxt)
                q.append((nxt, d + 1))
            buckets[key] = []
    return 0

def peak_overlap(intervals):
    if not intervals:
        return (0, None)
    events = []
    for s, e in intervals:
        if e <= s:
            continue
        events.append((s, 1))
        events.append((e, -1))
    if not events:
        return (0, None)
    events.sort(key=lambda x: (x[0], x[1]))
    best = 0
    best_t = None
    cur = 0
    for t, d in events:
        cur += d
        if d == 1 and cur > best:
            best = cur
            best_t = t
    if best == 0:
        return (0, None)
    return (best, best_t)

def run_program(program):
    stack = []
    mem = [0] * 16
    out = []
    pc = 0
    steps = 0
    n = len(program)
    LIMIT = 2000000
    while pc < n:
        steps += 1
        if steps > LIMIT:
            return None
        ins = program[pc]
        op = ins[0]
        if op == "PUSH":
            stack.append(ins[1])
            pc += 1
        elif op == "POP":
            if not stack:
                return None
            stack.pop()
            pc += 1
        elif op in ("ADD", "SUB", "MUL"):
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            if op == "ADD":
                stack.append(a + b)
            elif op == "SUB":
                stack.append(a - b)
            else:
                stack.append(a * b)
            pc += 1
        elif op == "DUP":
            if not stack:
                return None
            stack.append(stack[-1])
            pc += 1
        elif op == "SWAP":
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
            pc += 1
        elif op == "LOAD":
            i = ins[1]
            if not (0 <= i < 16):
                return None
            stack.append(mem[i])
            pc += 1
        elif op == "STORE":
            i = ins[1]
            if not (0 <= i < 16) or not stack:
                return None
            mem[i] = stack.pop()
            pc += 1
        elif op == "PRINT":
            if not stack:
                return None
            out.append(stack.pop())
            pc += 1
        elif op == "JMP":
            t = ins[1]
            if not (0 <= t <= n):
                return None
            pc = t
        elif op == "JZ":
            if not stack:
                return None
            t = ins[1]
            if not (0 <= t <= n):
                return None
            v = stack.pop()
            pc = t if v == 0 else pc + 1
        elif op == "HALT":
            return out
        else:
            return None
    return out

def roman_value(s):
    if not isinstance(s, str) or not s:
        return None
    vals = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    for ch in s:
        if ch not in vals:
            return None
    total = 0
    i = 0
    while i < len(s):
        v = vals[s[i]]
        if i + 1 < len(s) and vals[s[i + 1]] > v:
            total += vals[s[i + 1]] - v
            i += 2
        else:
            total += v
            i += 1
    if total < 1 or total > 3999:
        return None
    table = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"),
             (90, "XC"), (50, "L"), (40, "XL"), (10, "X"), (9, "IX"),
             (5, "V"), (4, "IV"), (1, "I")]
    out = []
    rest = total
    for value, sym in table:
        while rest >= value:
            out.append(sym)
            rest -= value
    if "".join(out) != s:
        return None
    return total

def parse_duration(s):
    if not isinstance(s, str) or not s:
        return None
    neg = False
    body = s
    if body[0] == "-":
        neg = True
        body = body[1:]
    if not body:
        return None
    units = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    order = ["d", "h", "m", "s"]
    last_rank = -1
    total = 0
    i = 0
    n = len(body)
    while i < n:
        start = i
        while i < n and body[i].isdigit():
            i += 1
        if i == start:
            return None
        num = int(body[start:i])
        if i >= n:
            return None
        u = body[i]
        if u not in units:
            return None
        rank = order.index(u)
        if rank <= last_rank:
            return None
        last_rank = rank
        total += num * units[u]
        i += 1
    return -total if neg else total

from collections import deque

def allow_flags(timestamps, limit, window):
    out = []
    accepted = deque()
    for t in timestamps:
        while accepted and accepted[0] <= t - window:
            accepted.popleft()
        if limit > 0 and len(accepted) < limit:
            accepted.append(t)
            out.append(True)
        else:
            out.append(False)
    return out

def fewest_coins(coins, amount):
    if amount == 0:
        return 0
    INF = float("inf")
    dp = [0] + [INF] * amount
    for c in set(coins):
        if c <= 0 or c > amount:
            continue
        for v in range(c, amount + 1):
            alt = dp[v - c] + 1
            if alt < dp[v]:
                dp[v] = alt
    return -1 if dp[amount] == INF else dp[amount]

def longest_shared(a, b):
    n, m = len(a), len(b)
    if n == 0 or m == 0:
        return ""
    prev = [0] * (m + 1)
    rows = []
    for i in range(n):
        cur = [0] * (m + 1)
        ai = a[i]
        for j in range(m):
            if ai == b[j]:
                cur[j + 1] = prev[j] + 1
            else:
                cur[j + 1] = cur[j] if cur[j] >= prev[j + 1] else prev[j + 1]
        rows.append(cur)
        prev = cur
    out = []
    i, j = n, m
    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            out.append(a[i - 1])
            i -= 1
            j -= 1
        else:
            up = rows[i - 2][j] if i >= 2 else 0
            left = rows[i - 1][j - 1]
            if up >= left:
                i -= 1
            else:
                j -= 1
    return "".join(reversed(out))

def longest_repeat(s, k):
    n = len(s)
    if k <= 0:
        return n
    if k == 1:
        return n
    if k > n:
        return 0
    MAXN = 2 * n + 5
    link = [-1] * MAXN
    length = [0] * MAXN
    cnt = [0] * MAXN
    trans = [None] * MAXN
    trans[0] = {}
    size = 1
    last = 0
    for ch in s:
        cur = size
        size += 1
        length[cur] = length[last] + 1
        cnt[cur] = 1
        trans[cur] = {}
        p = last
        while p != -1 and ch not in trans[p]:
            trans[p][ch] = cur
            p = link[p]
        if p == -1:
            link[cur] = 0
        else:
            q = trans[p][ch]
            if length[p] + 1 == length[q]:
                link[cur] = q
            else:
                clone = size
                size += 1
                length[clone] = length[p] + 1
                trans[clone] = dict(trans[q])
                link[clone] = link[q]
                cnt[clone] = 0
                while p != -1 and trans[p].get(ch) == q:
                    trans[p][ch] = clone
                    p = link[p]
                link[q] = clone
                link[cur] = clone
        last = cur
    order = sorted(range(1, size), key=lambda v: length[v], reverse=True)
    for v in order:
        pl = link[v]
        if pl > 0:
            cnt[pl] += cnt[v]
    best = 0
    for v in range(1, size):
        if cnt[v] >= k and length[v] > best:
            best = length[v]
    return best

def full_match(pattern, text):
    # --- node store: each node is [kind, data, out1, out2]
    # kind 'c' -> data is a predicate over one char, out1 is next
    # kind 's' -> split, out1/out2 are the two branches
    nodes = []

    def new(kind, data):
        nodes.append([kind, data, None, None])
        return len(nodes) - 1

    pos = 0
    n = len(pattern)

    def peek():
        return pattern[pos] if pos < n else None

    def parse_class():
        # pattern[pos] is just past '['
        nonlocal pos
        neg = False
        if peek() == '^':
            neg = True
            pos += 1
        items = []
        while pos < n and pattern[pos] != ']':
            if pattern[pos] == '\\':
                pos += 1
                lo = pattern[pos]
                pos += 1
            else:
                lo = pattern[pos]
                pos += 1
            if pos + 1 < n and pattern[pos] == '-' and pattern[pos + 1] != ']':
                pos += 1
                if pattern[pos] == '\\':
                    pos += 1
                hi = pattern[pos]
                pos += 1
                items.append((lo, hi))
            else:
                items.append((lo, lo))
        pos += 1  # skip ']'

        def pred(ch, items=tuple(items), neg=neg):
            inside = any(a <= ch <= b for a, b in items)
            return (not inside) if neg else inside
        return pred

    def parse_atom():
        nonlocal pos
        ch = pattern[pos]
        if ch == '(':
            pos += 1
            frag = parse_alt()
            pos += 1  # skip ')'
            return frag
        if ch == '[':
            pos += 1
            pred = parse_class()
            i = new('c', pred)
            return (i, [(i, 2)])
        if ch == '.':
            pos += 1
            i = new('c', lambda c: True)
            return (i, [(i, 2)])
        if ch == '\\':
            pos += 1
            lit = pattern[pos]
            pos += 1
            i = new('c', lambda c, lit=lit: c == lit)
            return (i, [(i, 2)])
        pos += 1
        i = new('c', lambda c, lit=ch: c == lit)
        return (i, [(i, 2)])

    def patch(outs, target):
        for idx, slot in outs:
            nodes[idx][slot] = target

    def parse_repeat():
        nonlocal pos
        start, outs = parse_atom()
        while pos < n and pattern[pos] in '*+?':
            op = pattern[pos]
            pos += 1
            if op == '*':
                s = new('s', None)
                nodes[s][2] = start
                patch(outs, s)
                start, outs = s, [(s, 3)]
            elif op == '+':
                s = new('s', None)
                nodes[s][2] = start
                patch(outs, s)
                outs = [(s, 3)]
            else:
                s = new('s', None)
                nodes[s][2] = start
                new_outs = list(outs) + [(s, 3)]
                start, outs = s, new_outs
        return start, outs

    def parse_concat():
        nonlocal pos
        start = None
        outs = []
        while pos < n and pattern[pos] not in '|)':
            s2, o2 = parse_repeat()
            if start is None:
                start, outs = s2, o2
            else:
                patch(outs, s2)
                outs = o2
        if start is None:
            s = new('s', None)          # epsilon fragment
            return s, [(s, 2), (s, 3)]
        return start, outs

    def parse_alt():
        nonlocal pos
        start, outs = parse_concat()
        while pos < n and pattern[pos] == '|':
            pos += 1
            s2, o2 = parse_concat()
            s = new('s', None)
            nodes[s][2] = start
            nodes[s][3] = s2
            start = s
            outs = outs + o2
        return start, outs

    start, outs = parse_alt()
    MATCH = -1
    patch(outs, MATCH)

    # --- Thompson simulation
    def add(state, cur, seen):
        stack = [state]
        while stack:
            st = stack.pop()
            if st is None:
                st = MATCH
            if st in seen:
                continue
            seen.add(st)
            if st == MATCH:
                cur.add(MATCH)
                continue
            if nodes[st][0] == 's':
                stack.append(nodes[st][2])
                stack.append(nodes[st][3])
            else:
                cur.add(st)

    cur = set()
    add(start, cur, set())
    for ch in text:
        nxt = set()
        seen = set()
        for st in cur:
            if st == MATCH:
                continue
            if nodes[st][1](ch):
                add(nodes[st][2], nxt, seen)
        cur = nxt
        if not cur:
            return False
    return MATCH in cur

