def lcs_length(a, b):
    n = len(a)
    m = len(b)
    if n == 0 or m == 0:
        return 0
    if n < m:
        a, b = b, a
        n, m = m, n
    # bitmask over a (length n)
    masks = {}
    for i, ch in enumerate(a):
        masks[ch] = masks.get(ch, 0) | (1 << i)
    full = (1 << n) - 1
    V = full
    for ch in b:
        M = masks.get(ch, 0)
        U = V & M
        V = (V + U) | (V - U)
        V &= full
    return n - bin(V & full).count('1')

