    from datetime import date, timedelta
    pat = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}\Z")

    def parse(s):
        if not isinstance(s, str) or not pat.match(s):
            raise ValueError("bad date %r" % (s,))
