        raise ValueError("days")
    if isinstance(weekend, bool):
        raise ValueError("weekend")
    if isinstance(weekend, int):
        if 1 <= weekend <= 7:
            off = {(weekend + 4) % 7, (weekend + 5) % 7}
        elif 11 <= weekend <= 17:
            off = {(weekend - 12) % 7}
        else:
            raise ValueError("weekend code")
    elif isinstance(weekend, str) and len(weekend) == 7 and set(weekend) <= {"0", "1"} \
