def sheet_round(func, number, *args):
    import re
    from decimal import Decimal, ROUND_HALF_UP, ROUND_UP, ROUND_DOWN, ROUND_CEILING, \
        ROUND_FLOOR, localcontext

    num_re = re.compile(r"-?[0-9]+(\.[0-9]+)?\Z")

    def num(x):
        if isinstance(x, bool):
            raise ValueError("bool")
        if isinstance(x, int):
            return Decimal(x)
        if isinstance(x, str) and num_re.match(x):
            return Decimal(x)
        raise ValueError("bad number %r" % (x,))

    def integer(x):
        if isinstance(x, bool) or not isinstance(x, int):
            raise ValueError("bad int %r" % (x,))
        return x

