        if d == 0:
            return "0"
        s = format(d, "f")
        if "." in s:
            s = s.rstrip("0").rstrip(".")
        return s

    def to_multiple(x, m, rounding):
        # x / m rounded to an integer with the given rule, times m (m > 0)
        q = (x / m).quantize(Decimal(1), rounding=rounding)
        return q * m

