def span_label(start, end):
    import re, calendar
    from datetime import date
    pat = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}\Z")

    def parse(s):
        if not isinstance(s, str) or not pat.match(s):
            return None
        try:
            return date(int(s[:4]), int(s[5:7]), int(s[8:]))
        except ValueError:
            return None

    a, b = parse(start), parse(end)
    if a is None or b is None:
        return "#VALUE!"
    sign = ""
    if b < a:
        a, b, sign = b, a, "-"

    def add_months(d, k):
        y, m = divmod(d.month - 1 + k, 12)
        y += d.year
        m += 1
        return date(y, m, min(d.day, calendar.monthrange(y, m)[1]))

    k = 0
    while add_months(a, k + 1) <= b:
        k += 1
    years, months = divmod(k, 12)
    days = (b - add_months(a, k)).days
    weeks, days = divmod(days, 7)
    parts = [f"{v}{u}" for v, u in ((years, "y"), (months, "m"), (weeks, "w"), (days, "d")) if v]
    return sign + (" ".join(parts) if parts else "0d")

