    # (cost -value, cap 1). Each augmenting path adds one machine; gains never grow,
    # so stop when a gain no longer beats machine_cost.
    pts = sorted({s for s, e, v in tasks} | {e + gap for s, e, v in tasks})
    idx = {p: i for i, p in enumerate(pts)}
    n = len(pts)
    to, cap, cost, head, nxt = [], [], [], [-1] * n, []

    def add(u, w, c, cs):
        for a, b, cc, cst in ((u, w, c, cs), (w, u, 0, -cs)):
            to.append(b); cap.append(cc); cost.append(cst)
            nxt.append(head[a]); head[a] = len(to) - 1

    for i in range(n - 1):
        add(i, i + 1, k, 0)
    for s, e, v in tasks:
        add(idx[s], idx[e + gap], 1, -v)
    # initial potentials: shortest distances on the DAG (all edges go forward)
    INF = float("inf")
    pot = [INF] * n
    pot[0] = 0
    for u in range(n):
        if pot[u] == INF:
            continue
        e = head[u]
        while e != -1:
            if cap[e] > 0 and pot[u] + cost[e] < pot[to[e]]:
                pot[to[e]] = pot[u] + cost[e]
            e = nxt[e]
    total = 0
    for _ in range(k):
        dist = [INF] * n
        prev = [-1] * n
        dist[0] = 0
        for _round in range(n):
            changed = False
            for u in range(n):
                if dist[u] == INF:
                    continue
                e = head[u]
                while e != -1:
                    if cap[e] > 0:
                        w = to[e]
                        nd = dist[u] + cost[e] + pot[u] - pot[w]
                        if nd < dist[w]:
                            dist[w] = nd
                            prev[w] = e
                            changed = True
                    e = nxt[e]
            if not changed:
                break
        if dist[n - 1] == INF:
            break
        for u in range(n):
            if dist[u] < INF:
                pot[u] += dist[u]
        path_cost = pot[n - 1] - pot[0]
        gain = -path_cost
        if gain <= machine_cost:
            break
        total += gain - machine_cost
        w = n - 1
        while w != 0:
            e = prev[w]
            cap[e] -= 1
            cap[e ^ 1] += 1
            w = to[e ^ 1]
    return total
